  const visited = new Set();
  function visit(node) {
    if (visited.has(node)) {
      return;
    }
    visited.add(node);
    for (let next = 0; next < numberOfNodes; next++) {
      if (next !== node && input.trust[node][next] > input.k) {
        visit(next);
      }
    }
  }
  let networks = 0;
  for (let node = 0; node < numberOfNodes; node++) {
    if (!visited.has(node)) {
      networks++;
      visit(node);
    }
  }
  return networks;
}

